const expiredPayload = Buffer.from(JSON.stringify({ sub: 'user_42', exp: Date.now() - 60000 })).toString('base64url');

console.log('Valid:', authenticateHeader('Bearer ' + validPayload + '.' + secret, secret));
console.log('Expired:', authenticateHeader('Bearer ' + expiredPayload + '.' + secret, secret));
console.log('Bad sig:', authenticateHeader('Bearer ' + validPayload + '.WRONG', secret));
console.log('Empty:', authenticateHeader('Bearer ', secret));
console.log('Missing header:', authenticateHeader(null, secret));
