                  "command": "node --input-type=module -e "
import { authenticateHeader } from './src/auth/session_guard.mjs';
import assert from 'node:assert';

const secret = 'SECRET_123';
const validPayload = Buffer.from(JSON.stringify({ sub: 'user_42', exp: Date.now() + 60000 })).toString('base64url');
const expiredPayload = Buffer.from(JSON.stringify({ sub: 'user_42', exp: Date.now() - 60000 })).toString('base64url');

const r1 = authenticateHeader('Bearer ' + validPayload + '.' + secret, secret);
assert.deepStrictEqual(r1, { valid: true, userId: 'user_42' });

const r2 = authenticateHeader('Bearer ' + expiredPayload + '.' + secret, secret);
assert.strictEqual(r2.valid, false);
assert.ok(r2.reason);

const r3 = authenticateHeader('Bearer ' + validPayload + '.WRONG', secret);
assert.deepStrictEqual(r3, { valid: false, reason: 'BAD_SIGNATURE' });

const r4 = authenticateHeader('Bearer ', secret);
assert.deepStrictEqual(r4, { valid: false, reason: 'EMPTY_TOKEN' });

const r5 = authenticateHeader(null, secret);
assert.strictEqual(r5.valid, false);
assert.ok(r5.reason);
""
